  function dateTime(value){return esc(new Date(value).toLocaleString(lang==='en'?'en-GB':'ar-SA',{timeZone:'Asia/Riyadh',calendar:'gregory',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}));}
  let managerCardOffset=view.managerCardOffset||0,managerCardFocus=view.managerCardFocus||'';
